/* ============================================================
   ShiftWise Design System
   ============================================================ */

/* ── 1. Primitive Tokens (OKLCH) ─────────────────────────── */
:root {
  /* Primary Blue Scale (hue ~255) */
  --blue-50:  oklch(97%  0.02 255);
  --blue-100: oklch(93%  0.04 255);
  --blue-200: oklch(85%  0.08 255);
  --blue-300: oklch(75%  0.14 255);
  --blue-400: oklch(65%  0.19 255);
  --blue-500: oklch(55%  0.22 255);
  --blue-600: oklch(47%  0.20 255);
  --blue-700: oklch(39%  0.17 255);
  --blue-800: oklch(30%  0.13 255);
  --blue-900: oklch(22%  0.09 255);

  /* Accent Coral/Red Scale (hue ~25) */
  --coral-50:  oklch(96%  0.03 25);
  --coral-100: oklch(92%  0.06 25);
  --coral-200: oklch(84%  0.12 25);
  --coral-300: oklch(75%  0.18 25);
  --coral-400: oklch(67%  0.22 25);
  --coral-500: oklch(60%  0.20 25);
  --coral-600: oklch(52%  0.17 25);
  --coral-700: oklch(44%  0.14 25);

  /* Neutral Gray Scale (hue ~255, very low chroma) */
  --gray-50:  oklch(98% 0.005 255);
  --gray-100: oklch(95% 0.01  255);
  --gray-200: oklch(90% 0.015 255);
  --gray-300: oklch(80% 0.02  255);
  --gray-400: oklch(65% 0.025 255);
  --gray-500: oklch(50% 0.03  255);
  --gray-600: oklch(40% 0.025 255);
  --gray-700: oklch(30% 0.02  255);
  --gray-800: oklch(20% 0.015 255);
  --gray-900: oklch(12% 0.01  255);

  /* Green (success) */
  --green-50:  oklch(97% 0.03 145);
  --green-500: oklch(55% 0.18 145);
  --green-600: oklch(47% 0.16 145);

  /* ── 2. Semantic Tokens ─────────────────────────────────── */
  --color-primary:   var(--blue-500);
  --color-primary-hover: var(--blue-600);
  --color-accent:    var(--coral-400);
  --color-accent-hover: var(--coral-500);
  --color-bg:        var(--gray-50);
  --color-surface:   #ffffff;
  --color-surface-raised: var(--gray-100);
  --color-text:      var(--gray-900);
  --color-text-secondary: var(--gray-600);
  --color-text-muted: var(--gray-400);
  --color-border:    var(--gray-200);
  --color-success:   var(--green-500);
  --color-success-bg: var(--green-50);

  /* Spacing (8px base) */
  --space-1: 0.25rem;   /* 4px  */
  --space-2: 0.5rem;    /* 8px  */
  --space-3: 0.75rem;   /* 12px */
  --space-4: 1rem;      /* 16px */
  --space-5: 1.25rem;   /* 20px */
  --space-6: 1.5rem;    /* 24px */
  --space-8: 2rem;      /* 32px */
  --space-10: 2.5rem;   /* 40px */
  --space-12: 3rem;     /* 48px */
  --space-16: 4rem;     /* 64px */
  --space-20: 5rem;     /* 80px */
  --space-24: 6rem;     /* 96px */

  /* Typography */
  --font-heading: "Poppins", system-ui, -apple-system, sans-serif;
  --font-body:    "Inter", system-ui, -apple-system, sans-serif;

  /* Type scale (fluid via clamp in rules) */
  --text-xs:   clamp(0.75rem, 0.7rem + 0.25vw, 0.875rem);
  --text-sm:   clamp(0.875rem, 0.8rem + 0.35vw, 1rem);
  --text-base: clamp(1rem, 0.9rem + 0.5vw, 1.125rem);
  --text-lg:   clamp(1.125rem, 1rem + 0.65vw, 1.375rem);
  --text-xl:   clamp(1.375rem, 1.1rem + 1.35vw, 2rem);
  --text-2xl:  clamp(1.75rem, 1.2rem + 2.75vw, 3rem);
  --text-3xl:  clamp(2.25rem, 1.4rem + 4.25vw, 4rem);
  --text-4xl:  clamp(2.75rem, 1.5rem + 6.25vw, 5rem);

  /* Radii */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 oklch(0% 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px oklch(0% 0 0 / 0.07), 0 2px 4px -2px oklch(0% 0 0 / 0.07);
  --shadow-lg: 0 10px 15px -3px oklch(0% 0 0 / 0.08), 0 4px 6px -4px oklch(0% 0 0 / 0.08);
  --shadow-xl: 0 20px 25px -5px oklch(0% 0 0 / 0.08), 0 8px 10px -6px oklch(0% 0 0 / 0.08);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  /* Layout */
  --container-max: 1200px;
  --container-padding: var(--space-6);
}

/* ── 3. Reset & Base ─────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }
body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
}
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--color-text);
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
ul, ol { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
input, textarea, select { font-family: inherit; font-size: inherit; }

/* ── 4. Utilities ────────────────────────────────────────── */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: var(--container-padding);
}
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

/* ── 5. Buttons ──────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-family: var(--font-heading); font-weight: 600; font-size: var(--text-sm);
  border-radius: var(--radius-md); transition: all var(--transition-base);
  white-space: nowrap;
}
.btn-primary {
  background: var(--color-primary); color: #fff;
}
.btn-primary:hover { background: var(--color-primary-hover); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-accent {
  background: var(--color-accent); color: #fff;
}
.btn-accent:hover { background: var(--color-accent-hover); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-outline {
  background: transparent; color: var(--color-primary);
  border: 2px solid var(--color-primary);
}
.btn-outline:hover { background: var(--blue-50); }
.btn-white {
  background: #fff; color: var(--color-primary);
}
.btn-white:hover { background: var(--gray-100); }
.btn-lg { padding: var(--space-4) var(--space-8); font-size: var(--text-base); border-radius: var(--radius-lg); }

/* ── 6. Cards ────────────────────────────────────────────── */
.card {
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  padding: var(--space-8);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }

/* ── 7. Forms ────────────────────────────────────────────── */
.form-group { margin-bottom: var(--space-5); }
.form-label {
  display: block; font-weight: 600; font-size: var(--text-sm);
  margin-bottom: var(--space-2); color: var(--color-text);
}
.form-input, .form-textarea, .form-select {
  width: 100%; padding: var(--space-3) var(--space-4);
  border: 1.5px solid var(--color-border); border-radius: var(--radius-md);
  background: var(--color-surface); color: var(--color-text);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}
.form-input:focus, .form-textarea:focus, .form-select:focus {
  outline: none; border-color: var(--color-primary);
  box-shadow: 0 0 0 3px oklch(55% 0.22 255 / 0.12);
}
.form-input::placeholder, .form-textarea::placeholder { color: var(--color-text-muted); }
.form-textarea { min-height: 140px; resize: vertical; }
.form-error { color: var(--coral-600); font-size: var(--text-sm); margin-top: var(--space-1); display: none; }
.form-group.has-error .form-error { display: block; }
.form-group.has-error .form-input { border-color: var(--coral-400); }

/* ── 8. Navigation ───────────────────────────────────────── */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}
.site-header .container {
  display: flex; align-items: center; justify-content: space-between;
  height: 72px;
}
.logo {
  font-family: var(--font-heading); font-weight: 800; font-size: 1.5rem;
  color: var(--color-primary); letter-spacing: -0.03em;
}
.logo span { color: var(--color-accent); }
.nav-links {
  display: flex; align-items: center; gap: var(--space-8);
}
.nav-link {
  font-weight: 500; font-size: var(--text-sm); color: var(--color-text-secondary);
  transition: color var(--transition-fast); position: relative;
}
.nav-link:hover, .nav-link.active { color: var(--color-primary); }
.nav-link.active::after {
  content: ''; position: absolute; bottom: -4px; left: 0; right: 0;
  height: 2px; background: var(--color-primary); border-radius: var(--radius-full);
}
.mobile-menu-btn {
  display: none; flex-direction: column; gap: 5px; padding: var(--space-2);
}
.mobile-menu-btn span {
  display: block; width: 24px; height: 2.5px; background: var(--color-text);
  border-radius: var(--radius-full); transition: all var(--transition-base);
}
.mobile-menu-btn[aria-expanded="true"] span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
.mobile-menu-btn[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
.mobile-menu-btn[aria-expanded="true"] span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }
.mobile-nav {
  position: fixed; inset: 72px 0 0 0; background: var(--color-surface);
  padding: var(--space-6); transform: translateX(100%);
  transition: transform var(--transition-base); z-index: 99;
  display: flex; flex-direction: column; gap: var(--space-4);
}
.mobile-nav.open { transform: translateX(0); }
.mobile-nav .nav-link { font-size: var(--text-lg); padding: var(--space-3) 0; border-bottom: 1px solid var(--color-border); }
.mobile-nav .btn { width: 100%; margin-top: var(--space-4); }

/* ── 9. Hero ─────────────────────────────────────────────── */
.hero {
  position: relative; overflow: hidden;
  padding: var(--space-20) 0 var(--space-16);
}
.hero-bg {
  position: absolute; inset: 0; z-index: 0; pointer-events: none;
}
.hero-bg .blob {
  position: absolute; border-radius: 50%; filter: blur(80px); opacity: 0.35;
}
.hero-bg .blob-1 { width: 500px; height: 500px; background: var(--blue-300); top: -10%; right: -5%; }
.hero-bg .blob-2 { width: 400px; height: 400px; background: var(--coral-200); bottom: -10%; left: -5%; opacity: 0.25; }
.hero .container { position: relative; z-index: 1; }
.hero-content { max-width: 680px; }
.hero-kicker {
  display: inline-flex; align-items: center; gap: var(--space-2);
  padding: var(--space-1) var(--space-3);
  background: var(--blue-50); color: var(--color-primary);
  font-size: var(--text-sm); font-weight: 600; border-radius: var(--radius-full);
  margin-bottom: var(--space-6);
}
.hero-title {
  font-size: var(--text-4xl); font-weight: 800; line-height: 1.05;
  margin-bottom: var(--space-6);
}
.hero-title .highlight { color: var(--color-primary); }
.hero-subtitle {
  font-size: var(--text-lg); color: var(--color-text-secondary);
  max-width: 560px; margin-bottom: var(--space-8); line-height: 1.65;
}
.hero-actions { display: flex; gap: var(--space-4); flex-wrap: wrap; }

/* ── 10. Section Layouts ─────────────────────────────────── */
.section { padding: var(--space-24) 0; }
.section-alt { background: var(--color-surface); }
.section-header { text-align: center; max-width: 640px; margin: 0 auto var(--space-16); }
.section-kicker {
  display: inline-block; font-size: var(--text-sm); font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.08em; color: var(--color-accent);
  margin-bottom: var(--space-4);
}
.section-title { font-size: var(--text-3xl); margin-bottom: var(--space-4); }
.section-subtitle { font-size: var(--text-lg); color: var(--color-text-secondary); }

/* ── 11. Feature Grid ────────────────────────────────────── */
.feature-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: var(--space-6);
}
.feature-item {
  background: var(--color-surface); border: 1px solid var(--color-border);
  border-radius: var(--radius-xl); padding: var(--space-8);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.feature-item:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); border-color: var(--blue-200); }
.feature-icon {
  width: 48px; height: 48px; border-radius: var(--radius-lg);
  background: var(--blue-50); color: var(--color-primary);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: var(--space-5);
}
.feature-item h3 { font-size: var(--text-xl); margin-bottom: var(--space-3); }
.feature-item p { color: var(--color-text-secondary); font-size: var(--text-sm); line-height: 1.6; }

/* ── 12. How It Works ────────────────────────────────────── */
.steps {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-8);
}
.step {
  position: relative; text-align: center;
}
.step-num {
  width: 56px; height: 56px; border-radius: var(--radius-full);
  background: var(--color-primary); color: #fff;
  font-family: var(--font-heading); font-weight: 800; font-size: 1.25rem;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto var(--space-6);
}
.step h3 { font-size: var(--text-lg); margin-bottom: var(--space-3); }
.step p { color: var(--color-text-secondary); font-size: var(--text-sm); }

/* ── 13. Testimonials ────────────────────────────────────── */
.testimonial-carousel { position: relative; max-width: 800px; margin: 0 auto; }
.testimonial-track { overflow: hidden; }
.testimonial-slides { display: flex; transition: transform var(--transition-slow); }
.testimonial-slide {
  min-width: 100%; padding: var(--space-4);
}
.testimonial-card {
  background: var(--color-surface); border: 1px solid var(--color-border);
  border-radius: var(--radius-2xl); padding: var(--space-10);
  text-align: center; box-shadow: var(--shadow-md);
}
.testimonial-quote {
  font-size: var(--text-xl); font-style: italic; line-height: 1.55;
  color: var(--color-text); margin-bottom: var(--space-8);
}
.testimonial-author { font-weight: 700; color: var(--color-text); }
.testimonial-role { font-size: var(--text-sm); color: var(--color-text-secondary); }
.testimonial-nav {
  display: flex; justify-content: center; gap: var(--space-4); margin-top: var(--space-8);
}
.testimonial-nav button {
  width: 44px; height: 44px; border-radius: var(--radius-full);
  border: 1.5px solid var(--color-border); background: var(--color-surface);
  color: var(--color-text); display: flex; align-items: center; justify-content: center;
  transition: all var(--transition-fast);
}
.testimonial-nav button:hover { background: var(--color-primary); color: #fff; border-color: var(--color-primary); }
.testimonial-dots {
  display: flex; justify-content: center; gap: var(--space-2); margin-top: var(--space-6);
}
.testimonial-dots button {
  width: 10px; height: 10px; border-radius: var(--radius-full); background: var(--gray-300);
  transition: background var(--transition-fast);
}
.testimonial-dots button.active { background: var(--color-primary); width: 28px; border-radius: var(--radius-full); }

/* ── 14. Stats Banner ────────────────────────────────────── */
.stats-banner {
  background: var(--color-primary); color: #fff; padding: var(--space-16) 0;
  position: relative; overflow: hidden;
}
.stats-banner .blob {
  position: absolute; border-radius: 50%; filter: blur(60px); opacity: 0.2;
}
.stats-banner .blob-1 { width: 300px; height: 300px; background: #fff; top: -50%; left: 10%; }
.stats-banner .blob-2 { width: 250px; height: 250px; background: var(--coral-200); bottom: -40%; right: 10%; }
.stats-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-8);
  position: relative; z-index: 1;
}
.stat-item { text-align: center; }
.stat-number {
  font-family: var(--font-heading); font-weight: 800; font-size: var(--text-3xl);
  line-height: 1; margin-bottom: var(--space-3);
}
.stat-label { font-size: var(--text-sm); opacity: 0.85; }

/* ── 15. Pricing ─────────────────────────────────────────── */
.pricing-toggle {
  display: flex; align-items: center; justify-content: center; gap: var(--space-4);
  margin-bottom: var(--space-12);
}
.pricing-toggle-label { font-weight: 600; font-size: var(--text-sm); color: var(--color-text-secondary); }
.pricing-toggle-label.active { color: var(--color-text); }
.toggle-switch {
  position: relative; width: 52px; height: 28px; background: var(--color-primary);
  border-radius: var(--radius-full); cursor: pointer; transition: background var(--transition-fast);
}
.toggle-switch::after {
  content: ''; position: absolute; top: 3px; left: 3px;
  width: 22px; height: 22px; background: #fff; border-radius: 50%;
  transition: transform var(--transition-base);
}
.toggle-switch.annual::after { transform: translateX(24px); }
.toggle-discount {
  display: inline-block; padding: var(--space-1) var(--space-2);
  background: var(--coral-100); color: var(--coral-700);
  font-size: 0.75rem; font-weight: 700; border-radius: var(--radius-full); margin-left: var(--space-2);
}
.pricing-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6);
  align-items: start;
}
.pricing-card {
  background: var(--color-surface); border: 1px solid var(--color-border);
  border-radius: var(--radius-2xl); padding: var(--space-8); text-align: center;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.pricing-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.pricing-card.featured {
  border-color: var(--color-primary); box-shadow: var(--shadow-lg);
  position: relative; transform: scale(1.03);
}
.pricing-card.featured:hover { transform: scale(1.03) translateY(-4px); }
.pricing-badge {
  position: absolute; top: -12px; left: 50%; transform: translateX(-50%);
  padding: var(--space-1) var(--space-4);
  background: var(--color-primary); color: #fff;
  font-size: 0.75rem; font-weight: 700; border-radius: var(--radius-full);
}
.pricing-name { font-size: var(--text-xl); margin-bottom: var(--space-2); }
.pricing-desc { font-size: var(--text-sm); color: var(--color-text-secondary); margin-bottom: var(--space-6); }
.pricing-price {
  font-family: var(--font-heading); font-weight: 800; font-size: var(--text-3xl);
  color: var(--color-text); margin-bottom: var(--space-6);
}
.pricing-price .period { font-size: var(--text-sm); font-weight: 500; color: var(--color-text-secondary); }
.pricing-features { text-align: left; margin-bottom: var(--space-8); }
.pricing-features li {
  display: flex; align-items: flex-start; gap: var(--space-3);
  padding: var(--space-3) 0; font-size: var(--text-sm);
  border-bottom: 1px solid var(--color-border);
}
.pricing-features li:last-child { border-bottom: none; }
.pricing-features .check { color: var(--green-500); flex-shrink: 0; margin-top: 2px; }
.pricing-features .cross { color: var(--gray-400); flex-shrink: 0; margin-top: 2px; }
.pricing-features .dim { color: var(--color-text-muted); }

/* ── 16. Pricing Table (detailed) ────────────────────────── */
.pricing-table-wrapper { overflow-x: auto; }
.pricing-table {
  width: 100%; border-collapse: collapse; font-size: var(--text-sm);
}
.pricing-table th, .pricing-table td {
  padding: var(--space-4) var(--space-6); text-align: left; border-bottom: 1px solid var(--color-border);
}
.pricing-table th {
  font-family: var(--font-heading); font-weight: 700; color: var(--color-text);
  background: var(--gray-100);
}
.pricing-table th:first-child { border-top-left-radius: var(--radius-lg); }
.pricing-table th:last-child { border-top-right-radius: var(--radius-lg); }
.pricing-table td { color: var(--color-text-secondary); }
.pricing-table tr:hover td { background: var(--gray-50); }
.pricing-table .plan-header { text-align: center; }
.pricing-table .plan-price { font-size: var(--text-xl); font-weight: 800; color: var(--color-text); }

/* ── 17. FAQ ─────────────────────────────────────────────── */
.faq-list { max-width: 720px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--color-border); }
.faq-question {
  width: 100%; display: flex; align-items: center; justify-content: space-between;
  padding: var(--space-6) 0; font-family: var(--font-heading); font-weight: 600;
  font-size: var(--text-base); text-align: left; color: var(--color-text);
  transition: color var(--transition-fast);
}
.faq-question:hover { color: var(--color-primary); }
.faq-question .icon {
  width: 24px; height: 24px; flex-shrink: 0; transition: transform var(--transition-base);
}
.faq-item.open .faq-question .icon { transform: rotate(180deg); }
.faq-answer {
  max-height: 0; overflow: hidden; transition: max-height var(--transition-slow), padding var(--transition-slow);
}
.faq-item.open .faq-answer {
  max-height: 300px; padding-bottom: var(--space-6);
}
.faq-answer p { color: var(--color-text-secondary); line-height: 1.65; }

/* ── 18. CTA Block ───────────────────────────────────────── */
.cta-block {
  background: var(--color-primary); color: #fff; padding: var(--space-20) 0;
  text-align: center; position: relative; overflow: hidden;
}
.cta-block .blob {
  position: absolute; border-radius: 50%; filter: blur(80px); opacity: 0.15;
}
.cta-block .blob-1 { width: 400px; height: 400px; background: #fff; top: -30%; left: -5%; }
.cta-block .blob-2 { width: 350px; height: 350px; background: var(--coral-200); bottom: -30%; right: -5%; }
.cta-block .container { position: relative; z-index: 1; }
.cta-block .section-title { color: #fff; margin-bottom: var(--space-4); }
.cta-block .section-subtitle { color: oklch(90% 0.02 255); margin-bottom: var(--space-8); }

/* ── 19. Footer ──────────────────────────────────────────── */
.site-footer {
  background: var(--gray-900); color: var(--gray-300); padding: var(--space-16) 0 var(--space-8);
}
.footer-grid {
  display: grid; grid-template-columns: 2fr repeat(4, 1fr); gap: var(--space-10);
  margin-bottom: var(--space-12);
}
.footer-brand .logo { color: #fff; margin-bottom: var(--space-4); }
.footer-brand p { font-size: var(--text-sm); line-height: 1.6; color: var(--gray-400); }
.footer-col h4 {
  font-family: var(--font-heading); font-weight: 700; font-size: var(--text-sm);
  color: #fff; text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: var(--space-5);
}
.footer-col a {
  display: block; font-size: var(--text-sm); color: var(--gray-400);
  padding: var(--space-1) 0; transition: color var(--transition-fast);
}
.footer-col a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid var(--gray-800); padding-top: var(--space-6);
  display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: var(--space-4);
}
.footer-bottom p { font-size: var(--text-sm); color: var(--gray-500); }

/* ── 20. Contact Page ────────────────────────────────────── */
.contact-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-16);
  align-items: start;
}
.contact-info h3 { font-size: var(--text-xl); margin-bottom: var(--space-4); }
.contact-info p { color: var(--color-text-secondary); margin-bottom: var(--space-6); }
.contact-detail {
  display: flex; align-items: flex-start; gap: var(--space-4); margin-bottom: var(--space-5);
}
.contact-detail .icon {
  width: 40px; height: 40px; border-radius: var(--radius-lg);
  background: var(--blue-50); color: var(--color-primary);
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
}
.contact-detail h4 { font-size: var(--text-sm); margin-bottom: var(--space-1); }
.contact-detail p { font-size: var(--text-sm); color: var(--color-text-secondary); margin: 0; }
.office-locations { margin-top: var(--space-12); }
.office-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6);
}
.office-card {
  background: var(--color-surface); border: 1px solid var(--color-border);
  border-radius: var(--radius-xl); padding: var(--space-6);
}
.office-card h4 { font-size: var(--text-lg); margin-bottom: var(--space-2); }
.office-card p { font-size: var(--text-sm); color: var(--color-text-secondary); }
.success-message {
  display: none; background: var(--color-success-bg); color: var(--color-success);
  padding: var(--space-4) var(--space-6); border-radius: var(--radius-md);
  margin-bottom: var(--space-6); font-weight: 600;
}
.success-message.show { display: block; }

/* ── 21. About Page ──────────────────────────────────────── */
.mission-section { padding: var(--space-24) 0; }
.mission-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-16); align-items: center;
}
.mission-content h2 { font-size: var(--text-3xl); margin-bottom: var(--space-6); }
.mission-content p { color: var(--color-text-secondary); margin-bottom: var(--space-5); line-height: 1.7; }
.mission-visual {
  background: var(--blue-50); border-radius: var(--radius-2xl);
  aspect-ratio: 4/3; display: flex; align-items: center; justify-content: center;
  border: 1px solid var(--blue-100);
}
.team-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-6);
}
.team-card {
  background: var(--color-surface); border: 1px solid var(--color-border);
  border-radius: var(--radius-xl); padding: var(--space-8); text-align: center;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.team-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.team-avatar {
  width: 80px; height: 80px; border-radius: var(--radius-full);
  background: var(--blue-100); color: var(--color-primary);
  font-family: var(--font-heading); font-weight: 800; font-size: 1.75rem;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto var(--space-5);
}
.team-card h4 { font-size: var(--text-lg); margin-bottom: var(--space-1); }
.team-card p { font-size: var(--text-sm); color: var(--color-text-secondary); }

/* ── 22. Integrations ────────────────────────────────────── */
.integration-cats {
  display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-6);
}
.integration-cat {
  background: var(--color-surface); border: 1px solid var(--color-border);
  border-radius: var(--radius-xl); padding: var(--space-8);
}
.integration-cat h3 { font-size: var(--text-xl); margin-bottom: var(--space-4); }
.integration-cat ul { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.integration-cat li {
  padding: var(--space-2) var(--space-4);
  background: var(--gray-100); border-radius: var(--radius-full);
  font-size: var(--text-sm); font-weight: 500; color: var(--color-text-secondary);
