  .mobile-menu-btn { display: flex; }
  .hero { padding: var(--space-12) 0 var(--space-10); }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; }
  .section { padding: var(--space-16) 0; }
  .feature-grid { grid-template-columns: 1fr; }
  .steps { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr 1fr; gap: var(--space-6); }
  .stats-banner { padding: var(--space-10) 0; }
  .team-grid { grid-template-columns: 1fr; }
  .office-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: var(--space-8); }
  .footer-bottom { flex-direction: column; text-align: center; }
  .cta-block { padding: var(--space-12) 0; }
  .pricing-table-wrapper { margin: 0 calc(var(--container-padding) * -1); padding: 0 var(--container-padding); }
}

@media (max-width: 480px) {
  .stats-grid { grid-template-columns: 1fr; }
}

